import EducationItem from "../education-item/education-item";

const educationData = [
  {
    name: "Ульяновский Государственный Технический Университет",
    faculty: "Информационных систем и технологий",
    speciality: "Информатика и вычислительная техника",
    qualification: reactPdf,
  },
  {
    description: "JavaScript. Архитектура клиентских приложений",
    img: jsar,
    date: "29 марта — 30 мая 2021",
    pdf: jsarPdf,
  },
];

export default function Education() {
  return (
    <section className="education">
      <h2>Образование</h2>
      {certificatesData.map((cer) => {
        return <EducationItem description={cer.description} img={cer.img} date={cer.date} pdf={cer.pdf} />;
      })}
    </section>
  );
}
